# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "json"
require "timekeeping_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "a 409 stale_generation answer marks nothing and sends no later batch in the same run" do
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([1, 2, 3, 4].map do |position|
      { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } }
    end)
    posts = []
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      posts << JSON.parse(JSON.generate(batch))
      TimekeepingRelay::Response.new(status: 409, body: { "reason" => "stale_generation" })
    end

    result = described_class.new(source:, endpoint:).deliver(limit: 2)

    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    expect(source.mark_calls.flatten).to be_empty
    expect(result).to eq(sent: 0, last_position: nil)
    # "It delivers in `outbox_position` order." Moving on to rows 3 and 4 after a refused batch would break the order.
    expect(posts.size).to eq(1)
    expect(posts.first["snapshots"].map { |item| item.fetch("outbox_position") }).to eq([1, 2])
  end
end


RSpec.describe TimekeepingRelay::Relay do
  it "a 200 whose counts do not cover the batch marks nothing sent" do
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([5, 6].map do |position|
      { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } }
    end)
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |_batch, idempotency_key:|
      # A proxy page or truncated answer: status 200 but only one of the two rows accounted for.
      TimekeepingRelay::Response.new(status: 200, body: { "applied" => 1, "ignored" => 0 })
    end

    result = described_class.new(source:, endpoint:).deliver(limit: 10)

    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    # The plan accepts a 200 only when applied + ignored equals the batch size.
    expect(source.mark_calls.flatten).to be_empty
    expect(result[:sent]).to eq(0)
  end
end


RSpec.describe TimekeepingRelay::Relay do
  it "positions with gaps are marked by their exact values, never as a range" do
    source = Class.new do
      attr_reader :mark_calls

      def initialize(rows)
        @rows = rows
        @mark_calls = []
      end

      def unsent_after(position, limit)
        sent = @mark_calls.flatten
        @rows.select { |row| row["outbox_position"] > position && !sent.include?(row["outbox_position"]) }
             .sort_by { |row| row["outbox_position"] }.first(limit)
      end

      def mark_sent(positions)
        @mark_calls << positions.to_a
        nil
      end
    end.new([12, 3, 7].map do |position|
      { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } }
    end)
    posted = []
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      snapshots = JSON.parse(JSON.generate(batch))["snapshots"]
      posted.concat(snapshots.map { |item| item["outbox_position"] })
      TimekeepingRelay::Response.new(status: 200, body: { "applied" => snapshots.size, "ignored" => 0 })
    end

    result = described_class.new(source:, endpoint:).deliver(limit: 2)

    # "It delivers in `outbox_position` order." A rolled-back write leaves gaps, so positions 4..6 and 8..11 never existed.
    expect(posted).to eq([3, 7, 12])
    expect(source.mark_calls).to eq([[3, 7], [12]])
    expect(result).to eq(sent: 3, last_position: 12)
  end
end


RSpec.describe TimekeepingRelay::Relay do
  it "a crash in mark_sent after a 200 resends the same batch under the same key" do
    source = Class.new do
      attr_reader :marked

      def initialize(rows)
        @rows = rows
        @marked = []
        @fail_next_mark = true
      end

      def unsent_after(position, limit)
        @rows.select { |row| row["outbox_position"] > position && !@marked.include?(row["outbox_position"]) }
             .sort_by { |row| row["outbox_position"] }.first(limit)
      end

      def mark_sent(positions)
        if @fail_next_mark
          @fail_next_mark = false
          raise IOError, "database went away"
        end
        @marked.concat(positions)
        nil
      end
    end.new([1, 2].map do |position|
      { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } }
    end)
    calls = []
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      body = JSON.parse(JSON.generate(batch))
      calls << [body, idempotency_key]
      TimekeepingRelay::Response.new(status: 200, body: { "applied" => body["snapshots"].size, "ignored" => 0 })
    end
    relay = described_class.new(source:, endpoint:)

    expect { relay.deliver(limit: 10) }.to raise_error(IOError)
    expect(source.marked).to be_empty

    result = relay.deliver(limit: 10)

    # "resends after an outage, and survives duplicates": the second run sends the identical batch and key,
    # so the consumer replays its stored answer instead of treating it as a new request.
    expect(calls.size).to eq(2)
    expect(calls[1]).to eq(calls[0])
    expect(source.marked).to eq([1, 2])
    expect(result).to eq(sent: 2, last_position: 2)
  end
end


RSpec.describe TimekeepingRelay::Relay do
  it "a pause set between two batches stops the second POST" do
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([1, 2, 3, 4].map do |position|
      { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } }
    end)
    paused = false
    posts = 0
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      posts += 1
      paused = true
      size = JSON.parse(JSON.generate(batch))["snapshots"].size
      TimekeepingRelay::Response.new(status: 200, body: { "applied" => size, "ignored" => 0 })
    end

    result = described_class.new(source:, endpoint:, paused: -> { paused }).deliver(limit: 2)

    # "A paused relay sends nothing until resumed": the check runs before every POST, not only at the start of a run.
    expect(posts).to eq(1)
    expect(source.mark_calls.flatten).to eq([1, 2])
    expect(result).to eq(sent: 2, last_position: 2)
  end
end


RSpec.describe TimekeepingRelay::Relay do
  it "a limit that is zero, negative or not an Integer is refused before any read" do
    reads = 0
    source = Object.new
    source.define_singleton_method(:unsent_after) do |_position, _limit|
      reads += 1
      []
    end
    source.define_singleton_method(:mark_sent) { |_positions| nil }
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) { |_batch, idempotency_key:| raise "must not be called" }
    relay = described_class.new(source:, endpoint:)

    # A bad limit passed straight to unsent_after could read the whole outbox into one POST.
    [0, -1, "2", nil, 2.5].each do |limit|
      expect { relay.deliver(limit:) }.to raise_error(ArgumentError)
    end
    expect(reads).to eq(0)
  end
end
